// The only module that drives the Spine API (spec 099, "Scene port"; Spine 4.3 bone poses). The runtime namespace
// and the graphics (textures, drawing, restore) are injected by a runtime module, so checks build scenes in Node with
// fake textures. Two runtimes use it: spine-webgl (spine_runtime_module.js: the scene draws into its own GL surface,
// skeleton world y up with its origin at the surface's bottom left, so a surface resize must happen before update())
// and spine-pixi-v8 (pixi_spine_runtime.js, spec 107: graphics.yDown, the skeleton world is y down like the surface,
// and graphics.createView gives the Pixi display object that draws the skeleton inside the WebGL scene). Placement
// and points are surface pixels with y down in both.
const SAMPLES_PER_CLIP = 24;
const EMPTY_ANIMATION = "<empty>";
const BONE_SETUP_KEYS = Object.freeze(["x", "y", "rotation", "scaleX", "scaleY"]);

export class SpineScene {
  #spine;
  #surface;
  #graphics;
  #atlas;
  #data;
  #skeleton;
  #state;
  #renderer = null;
  #view = null;
  #yDown;
  #placement = { x: 0, y: 0, scale: 1 };
  #localBounds;
  #points = new Map();
  #missingClips = new Set();
  #deltaClips = new Set();
  #mipmapped = false;
  #unsubscribe;
  #disposed = false;

  // Returns { scene, reason: null } or { scene: null, reason, error } (reasons: version-mismatch, page-missing,
  // texture-too-large, skeleton-invalid, skin-missing).
  static create({ spine, bundle, surface, graphics, runtimeVersion }) {
    if (!SpineScene.#sameLine(runtimeVersion, bundle.version)) return SpineScene.#failure("version-mismatch");
    let atlas = null;
    let mipmapped = false;
    try {
      atlas = new spine.TextureAtlas(bundle.atlasText);
      for (const page of atlas.pages) {
        const image = bundle.pages.get(page.name);
        if (!image) return SpineScene.#failure("page-missing", null, atlas);
        if (Math.max(page.width, page.height) > surface.maxTextureSize) {
          return SpineScene.#failure("texture-too-large", null, atlas);
        }
        page.setTexture(graphics.createTexture(image, page.pma));
        // Minification is the renderer's choice (spec 100 D3): mipmaps wherever the GPU can build them for the page.
        if (graphics.canMipmap?.(page.width, page.height) === true) {
          page.texture.setFilters(spine.TextureFilter.MipMapLinearLinear, spine.TextureFilter.Linear);
          mipmapped = true;
        }
      }
    } catch (error) {
      return SpineScene.#failure("skeleton-invalid", error, atlas);
    }
    let data;
    try {
      data = new spine.SkeletonJson(new spine.AtlasAttachmentLoader(atlas)).readSkeletonData(bundle.skeleton);
    } catch (error) {
      return SpineScene.#failure("skeleton-invalid", error, atlas);
    }
    const skin = bundle.skin ? data.findSkin(bundle.skin) : data.defaultSkin;
    if (bundle.skin && !skin) return SpineScene.#failure("skin-missing", null, atlas);
    return { scene: new SpineScene({ spine, surface, graphics, atlas, data, skin, mipmapped }), reason: null, error: null };
  }

  constructor({ spine, surface, graphics, atlas, data, skin, mipmapped = false }) {
    this.#spine = spine;
    this.#mipmapped = mipmapped;
    this.#surface = surface;
    this.#graphics = graphics;
    this.#atlas = atlas;
    this.#data = data;
    this.#yDown = graphics.yDown === true;
    // A view-drawing runtime owns the skeleton and state its display object draws; the scene drives them.
    const view = graphics.createView?.(data) ?? null;
    this.#view = view?.view ?? null;
    this.#skeleton = view?.skeleton ?? new spine.Skeleton(data);
    if (skin) this.#skeleton.setSkin(skin);
    this.#skeleton.setupPose();
    this.#state = view?.state ?? new spine.AnimationState(new spine.AnimationStateData(data));
    this.#localBounds = this.#measureBounds(skin);
    this.#unsubscribe = surface.onContextChange((lost) => {
      if (!lost) this.restoreContext();
    });
  }

  // x, y: the skeleton origin in surface pixels (y down); scale: surface pixels per skeleton unit.
  setPlacement(x, y, scale) {
    this.#placement.x = Number(x) || 0;
    this.#placement.y = Number(y) || 0;
    this.#placement.scale = Number(scale) > 0 ? Number(scale) : 1;
  }

  // Looping clip; the same clip keeps playing. From an empty track the clip fades in over mixSec. additive: the clip
  // plays as its change from its own first frame, added to the pose below (the critical tremble over the bend); the
  // clip is converted once for this scene.
  setLoop(track, clipName, mixSec = 0, additive = false) {
    const animation = this.#animation(clipName);
    if (!animation) {
      this.clearTrack(track, mixSec);
      return false;
    }
    if (additive) this.#toFirstFrameDelta(animation);
    const current = this.#state.getTrack(track);
    if (current && current.animation === animation && current.loop) return true;
    let entry;
    if (!current && mixSec > 0) {
      this.#state.setEmptyAnimation(track, 0);
      entry = this.#state.addAnimation(track, animation, true, 0);
    } else {
      entry = this.#state.setAnimation(track, animation, true);
    }
    entry.mixDuration = Math.max(0, mixSec);
    entry.additive = additive;
    return true;
  }

  setAnimation(track, clipName, loop = false, mixSec = 0) {
    const animation = this.#animation(clipName);
    if (!animation) {
      this.clearTrack(track, mixSec);
      return false;
    }
    const current = this.#state.getTrack(track);
    if (current && current.animation === animation && current.loop === loop && (!current.isComplete || !current.isComplete())) return true;
    let entry;
    if (!current && mixSec > 0) {
      this.#state.setEmptyAnimation(track, 0);
      entry = this.#state.addAnimation(track, animation, loop, 0);
    } else {
      entry = this.#state.setAnimation(track, animation, loop);
    }
    entry.mixDuration = Math.max(0, mixSec);
    return true;
  }

  setSlotVisible(slotName, visible) {
    const slot = this.#skeleton.findSlot(slotName);
    if (!slot) return false;
    const data = slot.data;
    if (visible) {
      if (data?.attachmentName) {
        try {
          this.#skeleton.setAttachment(slotName, data.attachmentName);
        } catch {
          const attachment = this.#skeleton.getAttachment?.(data.index, data.attachmentName);
          if (slot.pose?.setAttachment) slot.pose.setAttachment(attachment);
          else if (typeof slot.setAttachment === "function") slot.setAttachment(attachment);
        }
      }
      const alpha = data?.setupPose?.color?.a ?? 1;
      if (slot.pose?.color) slot.pose.color.a = alpha;
      else if (slot.color) slot.color.a = alpha;
    } else {
      try {
        this.#skeleton.setAttachment(slotName, null);
      } catch {
        if (slot.pose?.setAttachment) slot.pose.setAttachment(null);
        else if (typeof slot.setAttachment === "function") slot.setAttachment(null);
      }
      if (slot.pose?.color) slot.pose.color.a = 0;
      else if (slot.color) slot.color.a = 0;
    }
    return true;
  }

  // Clip held at ratio × duration (time scale 0) and blended with alpha: the fight bend sampled by load.
  setSampled(track, clipName, ratio, alpha) {
    const animation = this.#animation(clipName);
    if (!animation) {
      this.clearTrack(track, 0);
      return false;
    }
    let entry = this.#state.getTrack(track);
    if (!entry || entry.animation !== animation) {
      entry = this.#state.setAnimation(track, animation, false);
      entry.mixDuration = 0;
      entry.timeScale = 0;
    }
    entry.trackTime = SpineScene.#unit(ratio) * animation.duration;
    entry.alpha = SpineScene.#unit(alpha);
    return true;
  }

  clearTrack(track, mixSec = 0) {
    const current = this.#state.getTrack(track);
    if (!current || current.animation.name === EMPTY_ANIMATION) return;
    if (typeof this.#state.clearTrack === "function" && mixSec <= 0) {
      this.#state.clearTrack(track);
    } else {
      this.#state.setEmptyAnimation(track, Math.max(0, mixSec));
    }
  }

  setTrackTimeScale(track, timeScale) {
    const current = this.#state.getTrack(track);
    if (current && current.animation.name !== EMPTY_ANIMATION) current.timeScale = Math.max(0, Number(timeScale) || 0);
  }

  update(dtSec) {
    const dt = Math.max(0, Number(dtSec) || 0);
    const skeleton = this.#skeleton;
    this.#state.update(dt);
    // Bones start from the setup pose every frame, so blended tracks never build on the previous frame.
    skeleton.setupPoseBones();
    skeleton.x = this.#placement.x;
    skeleton.y = this.#yDown ? this.#placement.y : this.#surface.height - this.#placement.y;
    skeleton.scaleX = this.#placement.scale;
    skeleton.scaleY = this.#placement.scale;
    this.#state.apply(skeleton);
    skeleton.update(dt);
    skeleton.updateWorldTransform(this.#spine.Physics.update);
    if (this.#view) this.#graphics.viewUpdated(this.#view);
  }

  // The display object that draws the skeleton in the WebGL scene (spine-pixi-v8), or null (spine-webgl draws into
  // its surface through render()).
  getView() {
    return this.#view;
  }

  // Clears the surface and draws the skeleton; false while the context is lost. A view is drawn by its own renderer.
  render() {
    const surface = this.#surface;
    if (this.#disposed || surface.isContextLost()) return false;
    if (this.#view) return true;
    const renderer = this.#renderer ??= this.#graphics.createRenderer();
    const gl = surface.gl;
    const width = surface.width;
    const height = surface.height;
    gl.viewport(0, 0, width, height);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    renderer.camera.setViewport(width, height);
    renderer.camera.position.x = width / 2;
    renderer.camera.position.y = height / 2;
    renderer.begin();
    renderer.drawSkeleton(this.#skeleton);
    renderer.end();
    return true;
  }

  // A point attachment of that name, else a bone of that name, else the tip of the deepest bone; in surface pixels
  // (y down) for the last update(). Writes out.x / out.y.
  getPoint(name, out) {
    let point = this.#points.get(name);
    if (!point) {
      point = this.#resolvePoint(name);
      this.#points.set(name, point);
    }
    if (!point) return false;
    const pose = point.bone.appliedPose;
    out.x = pose.a * point.x + pose.b * point.y + pose.worldX;
    const worldY = pose.c * point.x + pose.d * point.y + pose.worldY;
    out.y = this.#yDown ? worldY : this.#surface.height - worldY;
    return true;
  }

  // Union of the setup pose and every clip's sampled poses, skeleton units (y up) at origin 0 and scale 1.
  getLocalBounds(out) {
    out.x = this.#localBounds.x;
    out.y = this.#localBounds.y;
    out.width = this.#localBounds.width;
    out.height = this.#localBounds.height;
    return out;
  }

  hasClip(clipName) {
    return Boolean(this.#data.findAnimation(clipName));
  }

  clipDuration(clipName) {
    return this.#data.findAnimation(clipName)?.duration ?? 0;
  }

  getMissingClips() {
    return [...this.#missingClips];
  }

  // True when the atlas pages were mipmapped (spec 100 D3); false keeps the atlas filter (WebGL 1, non-power-of-two).
  isMipmapped() {
    return this.#mipmapped;
  }

  // DEV inspection (spec 099 Phase 4). Clips of the skeleton with their durations.
  getClips() {
    return this.#data.animations.map((animation) => ({ name: animation.name, duration: animation.duration }));
  }

  // Bones with their setup values (bone space) and world position in surface pixels (y down) for the last update().
  getBones() {
    const height = this.#surface.height;
    const yDown = this.#yDown;
    return this.#skeleton.bones.map((bone) => {
      const setup = bone.data.setupPose;
      const pose = bone.appliedPose;
      return {
        name: bone.data.name, parent: bone.parent?.data.name ?? null,
        x: setup.x, y: setup.y, rotation: setup.rotation, scaleX: setup.scaleX, scaleY: setup.scaleY,
        worldX: pose.worldX, worldY: yDown ? pose.worldY : height - pose.worldY,
      };
    });
  }

  // Changes a bone's setup pose live (x, y, rotation, scaleX, scaleY; other keys are ignored) and re-measures the
  // bounds. Returns false for an unknown bone.
  setBoneSetup(name, values) {
    const data = this.#data.findBone(name);
    if (!data) return false;
    for (const key of BONE_SETUP_KEYS) {
      const value = Number(values?.[key]);
      if (values?.[key] !== undefined && Number.isFinite(value)) data.setupPose[key] = value;
    }
    this.#localBounds = this.#measureBounds(this.#skeleton.skin);
    return true;
  }

  restoreContext() {
    if (!this.#disposed) this.#graphics.restore();
  }

  dispose() {
    if (this.#disposed) return;
    this.#disposed = true;
    this.#unsubscribe();
    this.#renderer?.dispose();
    if (this.#view) this.#graphics.disposeView(this.#view);
    this.#atlas.dispose();
    this.#graphics.dispose();
  }

  #animation(clipName) {
    const animation = this.#data.findAnimation(clipName);
    if (!animation) this.#missingClips.add(String(clipName));
    return animation;
  }

  // Single-value timelines (rotate, translate x/y, scale x/y, ...) lose their first frame's value from every key and
  // every Bezier sample, so the clip starts at zero change; other timelines are left as they are.
  #toFirstFrameDelta(animation) {
    if (this.#deltaClips.has(animation)) return;
    this.#deltaClips.add(animation);
    for (const timeline of animation.timelines) {
      if (!(timeline instanceof this.#spine.CurveTimeline1)) continue;
      const frames = timeline.frames;
      const base = frames[1];
      for (let index = 1; index < frames.length; index += 2) frames[index] -= base;
      const curves = timeline.curves;
      for (let index = timeline.getFrameCount() + 1; index < curves.length; index += 2) curves[index] -= base;
    }
  }

  #resolvePoint(name) {
    const skeleton = this.#skeleton;
    const skin = skeleton.skin ?? this.#data.defaultSkin;
    for (const entry of skin?.getAttachments() ?? []) {
      if ((entry.placeholder ?? entry.name) === name && entry.attachment instanceof this.#spine.PointAttachment) {
        const bone = skeleton.slots[entry.slotIndex].bone;
        return { bone, x: entry.attachment.x, y: entry.attachment.y };
      }
    }
    const named = skeleton.findBone(name);
    if (named) return { bone: named, x: 0, y: 0 };
    let deepest = null;
    let deepestDepth = -1;
    for (const bone of skeleton.bones) {
      let depth = 0;
      for (let parent = bone.parent; parent; parent = parent.parent) depth += 1;
      if (bone.data.length > 0 && depth > deepestDepth) {
        deepest = bone;
        deepestDepth = depth;
      }
    }
    return deepest ? { bone: deepest, x: deepest.data.length, y: 0 } : null;
  }

  #measureBounds(skin) {
    const spine = this.#spine;
    const skeleton = new spine.Skeleton(this.#data);
    if (skin) skeleton.setSkin(skin);
    const state = new spine.AnimationState(new spine.AnimationStateData(this.#data));
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    // Bounds are skeleton units with y up; a y-down world mirrors them.
    const yDown = this.#yDown;
    const measure = () => {
      skeleton.updateWorldTransform(spine.Physics.update);
      const rect = skeleton.getBoundsRect();
      if (!(rect.width > 0 || rect.height > 0)) return;
      const bottom = yDown ? -(rect.y + rect.height) : rect.y;
      minX = Math.min(minX, rect.x);
      minY = Math.min(minY, bottom);
      maxX = Math.max(maxX, rect.x + rect.width);
      maxY = Math.max(maxY, bottom + rect.height);
    };
    skeleton.setupPose();
    measure();
    for (const animation of this.#data.animations) {
      for (let sample = 0; sample <= SAMPLES_PER_CLIP; sample += 1) {
        skeleton.setupPose();
        state.clearTracks();
        const entry = state.setAnimation(0, animation, false);
        entry.trackTime = (animation.duration * sample) / SAMPLES_PER_CLIP;
        state.apply(skeleton);
        measure();
      }
    }
    if (!Number.isFinite(minX)) return Object.freeze({ x: 0, y: 0, width: 0, height: 0 });
    return Object.freeze({ x: minX, y: minY, width: maxX - minX, height: maxY - minY });
  }

  static #sameLine(runtimeVersion, exportVersion) {
    const line = (version) => String(version || "").split(".").slice(0, 2);
    const [runtimeMajor, runtimeMinor] = line(runtimeVersion);
    const [exportMajor, exportMinor] = line(exportVersion);
    return Boolean(exportMajor && exportMinor) && runtimeMajor === exportMajor && runtimeMinor === exportMinor;
  }

  static #unit(value) {
    const number = Number(value);
    return Number.isFinite(number) ? Math.min(1, Math.max(0, number)) : 0;
  }

  static #failure(reason, error = null, atlas = null) {
    atlas?.dispose();
    return { scene: null, reason, error };
  }
}
